{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.cluster_category_size_depth as WITH unique_pincode_mapping AS ( SELECT UPPER(state) AS state, pincode FROM snitch_db.maplemonk.gs_pincode_mapping_lat_long_tier QUALIFY ROW_NUMBER() OVER (PARTITION BY pincode ORDER BY state DESC) = 1 ), online_data AS ( SELECT upper(a.sku) as sku, upper(a.sku_group) as sku_group, case when upper(category) like \'%DENIM%\' then \'JEANS\' else upper(category) end as category, b.state, sum(a.quantity) as online_sales FROM snitch_db.maplemonk.fact_items_snitch a left join unique_pincode_mapping b on a.pincode::varchar = b.pincode::varchar WHERE LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%eco%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%influ%\' AND LOWER(IFNULL(discount_code, \'n\')) NOT LIKE \'%snitch_rms%\' AND order_name NOT IN (\'2431093\',\'2422140\',\'2425364\',\'2430652\',\'2422237\',\'2420623\',\'2429832\',\'2422378\',\'2428311\',\'2429064\',\'2428204\',\'2421343\',\'2431206\',\'2430491\',\'2426682\',\'2426487\',\'2426458\',\'2423575\',\'2422431\',\'2423612\',\'2426625\',\'2428117\',\'2426894\',\'2425461\',\'2426570\',\'2423455\',\'2430777\',\'2426009\',\'2428245\',\'2427269\',\'2430946\',\'2425821\',\'2429986\',\'2429085\',\'2422047\',\'2430789\',\'2420219\',\'2428341\',\'2430444\',\'2426866\',\'2431230\',\'2425839\',\'2430980\',\'2427048\',\'2430597\',\'2420499\',\'2431050\',\'2420271\',\'2426684\',\'2428747\',\'2423523\',\'2431171\',\'2430830\',\'2425325\',\'2428414\',\'2429054\',\'2423596\') AND tags NOT IN (\'FLITS_LOGICERP\') and lower(tags) not like \'%creator%\' group by 1,2,3,4 ), online_size_table AS ( SELECT SKU, STATE, CATEGORY, online_sales as sales, CASE WHEN SKU LIKE \'SN%\' OR SKU LIKE \'4MSFR%\' OR SKU LIKE \'BP%\' THEN \'NA\' WHEN SKU LIKE \'SH%\' THEN CASE WHEN SKU LIKE \'%-39\' THEN \'XS\' WHEN SKU LIKE \'%-40\' THEN \'S\' WHEN SKU LIKE \'%-41\' THEN \'M\' WHEN SKU LIKE \'%-42\' THEN \'L\' WHEN SKU LIKE \'%-43\' THEN \'XL\' WHEN SKU LIKE \'%-44\' THEN \'XXL\' WHEN SKU LIKE \'%-45\' THEN \'3XL\' END WHEN SKU LIKE \'4M%\' THEN CASE WHEN SKU LIKE \'%-XS\' OR SKU LIKE \'%-28\' THEN \'XS\' WHEN SKU LIKE \'%-S\' OR SKU LIKE \'%-30\' THEN \'S\' WHEN SKU LIKE \'%-M\' OR SKU LIKE \'%-32\' THEN \'M\' WHEN SKU LIKE \'%-L\' OR SKU LIKE \'%-34\' THEN \'L\' WHEN SKU LIKE \'%-XL\' OR SKU LIKE \'%-36\' THEN \'XL\' WHEN SKU LIKE \'%-XXL\' OR SKU LIKE \'%-38\' THEN \'XXL\' WHEN SKU LIKE \'%-3XL\' OR SKU LIKE \'%-40\' THEN \'3XL\' WHEN SKU LIKE \'%-4XL\' OR SKU LIKE \'%-42\' THEN \'4XL\' WHEN SKU LIKE \'%-5XL\' OR SKU LIKE \'%-44\' THEN \'5XL\' WHEN SKU LIKE \'%-6XL\' OR SKU LIKE \'%-46\' THEN \'6XL\' WHEN SKU LIKE \'%-7XL\' OR SKU LIKE \'%-48\' THEN \'7XL\' WHEN SKU LIKE \'%-8XL\' OR SKU LIKE \'%-50\' THEN \'8XL\' ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SUBSTRING(SKU, LEN(SKU) - CHARINDEX(\'-\', REVERSE(SKU)) + 2))) ELSE \'NA\' END END ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SUBSTRING(SKU, LEN(SKU) - CHARINDEX(\'-\', REVERSE(SKU)) + 2))) ELSE \'NA\' END END AS SIZE FROM online_data ), unique_branch_mapping AS ( SELECT a.\"STORE CODE\" AS BRANCH_CODE, UPPER(a.\"END BILLING\") AS STATE, ROW_NUMBER() OVER (PARTITION BY a.\"STORE CODE\" ORDER BY UPPER(a.\"END BILLING\")) AS rn FROM snitch_db.maplemonk.MASTER_FILE AS a ), offline_sales AS ( SELECT UPPER(a.SKU) AS SKU, upper(a.sku_group) as sku_group, b.STATE as state, sum(a.SHIPPING_QUANTITY) - sum(a.RETURN_QUANTITY) - sum(a.CANCELLED_QUANTITY) as offline_sales FROM SNITCH_DB.MAPLEMONK.STORE_FACT_ITEMS_OFFLINE AS a LEFT JOIN unique_branch_mapping AS b ON b.BRANCH_CODE = a.BRANCH_CODE WHERE b.rn = 1 group by 1,2,3 ), offline_Data AS ( SELECT a.sku as sku, a.sku_group as sku_group, a.state as state, a.offline_sales as offline_sales, upper(b.category) as category from offline_sales a left join snitch_db.maplemonk.category_journey b on a.sku_group = upper(b.sku_group) WHERE b.CATEGORY IS NOT NULL QUALIFY ROW_NUMBER() OVER (PARTITION BY a.sku_group ORDER BY category DESC) = 1 ), offline_size_table AS ( SELECT SKU, STATE, CATEGORY, OFFLINE_SALES AS SALES, CASE WHEN SKU LIKE \'SN%\' OR SKU LIKE \'4MSFR%\' OR SKU LIKE \'BP%\' THEN \'NA\' WHEN SKU LIKE \'SH%\' THEN CASE WHEN SKU LIKE \'%-39\' THEN \'XS\' WHEN SKU LIKE \'%-40\' THEN \'S\' WHEN SKU LIKE \'%-41\' THEN \'M\' WHEN SKU LIKE \'%-42\' THEN \'L\' WHEN SKU LIKE \'%-43\' THEN \'XL\' WHEN SKU LIKE \'%-44\' THEN \'XXL\' WHEN SKU LIKE \'%-45\' THEN \'3XL\' END WHEN SKU LIKE \'4M%\' THEN CASE WHEN SKU LIKE \'%-XS\' OR SKU LIKE \'%-28\' THEN \'XS\' WHEN SKU LIKE \'%-S\' OR SKU LIKE \'%-30\' THEN \'S\' WHEN SKU LIKE \'%-M\' OR SKU LIKE \'%-32\' THEN \'M\' WHEN SKU LIKE \'%-L\' OR SKU LIKE \'%-34\' THEN \'L\' WHEN SKU LIKE \'%-XL\' OR SKU LIKE \'%-36\' THEN \'XL\' WHEN SKU LIKE \'%-XXL\' OR SKU LIKE \'%-38\' THEN \'XXL\' WHEN SKU LIKE \'%-3XL\' OR SKU LIKE \'%-40\' THEN \'3XL\' WHEN SKU LIKE \'%-4XL\' OR SKU LIKE \'%-42\' THEN \'4XL\' WHEN SKU LIKE \'%-5XL\' OR SKU LIKE \'%-44\' THEN \'5XL\' WHEN SKU LIKE \'%-6XL\' OR SKU LIKE \'%-46\' THEN \'6XL\' WHEN SKU LIKE \'%-7XL\' OR SKU LIKE \'%-48\' THEN \'7XL\' WHEN SKU LIKE \'%-8XL\' OR SKU LIKE \'%-50\' THEN \'8XL\' ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SPLIT_PART(SKU, \'-\', -1))) ELSE \'NA\' END END ELSE CASE WHEN POSITION(\'-\' IN SKU) > 0 THEN UPPER(TRIM(SPLIT_PART(SKU, \'-\', -1))) ELSE \'NA\' END END AS SIZE FROM offline_data ), Combined_Size AS ( SELECT state, category, size, sales FROM online_size_table UNION ALL SELECT state, category, size, sales FROM offline_size_table ), final_size_table AS ( SELECT STATE, CATEGORY, SALES, CASE WHEN SIZE IN (\'28\', \'XS\') THEN \'XS\' WHEN SIZE IN (\'30\', \'S\') THEN \'S\' WHEN SIZE IN (\'32\', \'M\') THEN \'M\' WHEN SIZE IN (\'34\', \'L\') THEN \'L\' WHEN SIZE IN (\'36\', \'XL\') THEN \'XL\' WHEN SIZE IN (\'38\', \'XXL\') THEN \'XXL\' WHEN SIZE IN (\'40\', \'3XL\', \'XXXL\') THEN \'3XL\' WHEN SIZE IN (\'42\', \'XXXXL\', \'4XL\') THEN \'4XL\' WHEN SIZE IN (\'44\', \'5XL\') THEN \'5XL\' WHEN SIZE IN (\'46\', \'6XL\') THEN \'6XL\' WHEN SIZE IN (\'48\', \'7XL\') THEN \'7XL\' WHEN SIZE IN (\'50\', \'8XL\') THEN \'8XL\' ELSE \'NA\' END AS SIZE FROM combined_size ), size_sum as ( SELECT state, category, size, SUM(sales) AS total_sales FROM final_size_table GROUP BY state, category, size ), total_size_sum as ( select state, category, sum(total_sales) as total from size_sum group by state, category ), size_perc_table AS ( SELECT a.total, a.state, a.category, b.total_sales, b.size, b.total_sales / NULLIF(COALESCE(a.total, 0), 0) AS size_perc FROM size_sum AS b JOIN total_size_sum AS a ON a.state = b.state AND a.category = b.category ), final_data AS ( SELECT p.state, p.category, p.XS_PERC, p.S_PERC, p.M_PERC, p.L_PERC, p.XL_PERC, p.XXL_PERC, p.\"3XL_PERC\", p.\"4XL_PERC\", p.\"5XL_PERC\", p.\"6XL_PERC\", p.\"7XL_PERC\", p.\"8XL_PERC\", p.NA_PERC, s.\"STORE CODE\" AS BRANCH_CODE, s.\"STORE NAME\", s.DEPT_IDEAL FROM ( SELECT state, category, SUM(CASE WHEN size = \'XS\' THEN size_perc ELSE 0 END) AS XS_PERC, SUM(CASE WHEN size = \'S\' THEN size_perc ELSE 0 END) AS S_PERC, SUM(CASE WHEN size = \'M\' THEN size_perc ELSE 0 END) AS M_PERC, SUM(CASE WHEN size = \'L\' THEN size_perc ELSE 0 END) AS L_PERC, SUM(CASE WHEN size = \'XL\' THEN size_perc ELSE 0 END) AS XL_PERC, SUM(CASE WHEN size = \'XXL\' THEN size_perc ELSE 0 END) AS XXL_PERC, SUM(CASE WHEN size = \'3XL\' THEN size_perc ELSE 0 END) AS \"3XL_PERC\", SUM(CASE WHEN size = \'4XL\' THEN size_perc ELSE 0 END) AS \"4XL_PERC\", SUM(CASE WHEN size = \'5XL\' THEN size_perc ELSE 0 END) AS \"5XL_PERC\", SUM(CASE WHEN size = \'6XL\' THEN size_perc ELSE 0 END) AS \"6XL_PERC\", SUM(CASE WHEN size = \'7XL\' THEN size_perc ELSE 0 END) AS \"7XL_PERC\", SUM(CASE WHEN size = \'8XL\' THEN size_perc ELSE 0 END) AS \"8XL_PERC\", SUM(CASE WHEN size = \'NA\' THEN size_perc ELSE 0 END) AS NA_PERC FROM size_perc_table GROUP BY state, category ) AS p JOIN ( SELECT a.\"STORE CODE\", a.\"STORE NAME\", UPPER(TRIM(a.\"END BILLING\")) AS STATE, a.\"DOI BOH\" AS DEPT_IDEAL FROM snitch_db.maplemonk.master_file AS a ) AS s ON UPPER(p.state) = UPPER(s.state) ) SELECT BRANCH_CODE, STATE, CATEGORY, \"STORE NAME\", DEPT_IDEAL, XS_PERC, S_PERC, M_PERC, L_PERC, XL_PERC, XXL_PERC, \"3XL_PERC\", \"4XL_PERC\", \"5XL_PERC\", \"6XL_PERC\", \"7XL_PERC\", \"8XL_PERC\", ROUND(XS_PERC * DEPT_IDEAL) AS XS_DEPTH, ROUND(S_PERC * DEPT_IDEAL) AS S_DEPTH, ROUND(M_PERC * DEPT_IDEAL) AS M_DEPTH, ROUND(L_PERC * DEPT_IDEAL) AS L_DEPTH, ROUND(XL_PERC * DEPT_IDEAL) AS XL_DEPTH, ROUND(XXL_PERC * DEPT_IDEAL) AS XXL_DEPTH, ROUND(\"3XL_PERC\" * DEPT_IDEAL) AS \"3XL_DEPTH\", ROUND(\"4XL_PERC\" * DEPT_IDEAL) AS \"4XL_DEPTH\", ROUND(\"5XL_PERC\" * DEPT_IDEAL) AS \"5XL_DEPTH\", ROUND(\"6XL_PERC\" * DEPT_IDEAL) AS \"6XL_DEPTH\", ROUND(\"7XL_PERC\" * DEPT_IDEAL) AS \"7XL_DEPTH\", ROUND(\"8XL_PERC\" * DEPT_IDEAL) AS \"8XL_DEPTH\" FROM FINAL_DATA where category != \'NA\' ; create or replace table snitch_db.maplemonk.STORE_METAFIELD_DELTA2 as WITH base AS ( SELECT BRANCH_CODE AS BRANCH_CODE , NEW_CATEGORY AS NEW_CATEGORY , COLLAR_NEW , MATERIAL_NEW , SLEEVE_TYPE , FIT , DESIGNS , COALESCE(INVENTORY, 0) + COALESCE(JIT_QTY, 0) AS stock , COALESCE(TOTAL_SALES, 0) AS sales FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER ), totals AS ( SELECT BRANCH_CODE AS BRANCH_CODE , NEW_CATEGORY AS NEW_CATEGORY , SUM(stock) AS cat_stock_total , SUM(sales) AS cat_sales_total FROM base GROUP BY BRANCH_CODE , NEW_CATEGORY ) SELECT b.BRANCH_CODE AS BRANCH_CODE , b.NEW_CATEGORY AS NEW_CATEGORY , b.COLLAR_NEW AS COLLAR_NEW , b.MATERIAL_NEW AS MATERIAL_NEW , b.SLEEVE_TYPE AS SLEEVE_TYPE , b.FIT AS FIT , b.DESIGNS AS DESIGNS , SUM(b.stock) AS \"Inventory+JIT_Qty\" , SUM(b.stock) AS \"Stock\" , SUM(b.sales) AS \"Sales\" , CASE WHEN t.cat_stock_total = 0 THEN 0 ELSE (SUM(b.stock) / t.cat_stock_total) END AS \"Stock% at category level\" , CASE WHEN t.cat_sales_total = 0 THEN 0 ELSE (SUM(b.sales) / t.cat_sales_total) END AS \"Sales% at category level\" , CASE WHEN t.cat_stock_total = 0 OR t.cat_sales_total = 0 OR SUM(b.stock) = 0 THEN 0 ELSE GREATEST( 0, ( ( SUM(b.sales) / NULLIF(t.cat_sales_total, 0) ) / ( SUM(b.stock) / NULLIF(t.cat_stock_total, 0) ) ) * SUM(b.stock) - SUM(b.stock) ) END AS \"meta_delta\" FROM base b JOIN totals t ON b.BRANCH_CODE = t.BRANCH_CODE AND b.NEW_CATEGORY = t.NEW_CATEGORY GROUP BY b.BRANCH_CODE , b.NEW_CATEGORY , b.COLLAR_NEW , b.MATERIAL_NEW , b.SLEEVE_TYPE , b.FIT , b.DESIGNS , t.cat_stock_total , t.cat_sales_total ORDER BY b.BRANCH_CODE , b.NEW_CATEGORY , b.COLLAR_NEW , b.MATERIAL_NEW , b.SLEEVE_TYPE , b.FIT , b.DESIGNS ; create or replace table snitch_db.maplemonk.ist_summary_v1 as WITH ist AS ( SELECT donor_store, donor_branch_code, receiver_store, receiver_branch_code, sku_code, SUM(qty) AS given_qty FROM snitch_db.maplemonk.ist WHERE TRY_TO_DATE(date, \'DD-MM-YYYY\') = ( SELECT MAX(TRY_TO_DATE(date, \'DD-MM-YYYY\')) FROM snitch_db.maplemonk.ist ) GROUP BY 1, 2, 3, 4, 5 ), ist_max_date AS ( SELECT MAX(TRY_TO_DATE(date, \'DD-MM-YYYY\')) AS max_date FROM snitch_db.maplemonk.ist ), sto AS ( SELECT FROM_PARTY AS donor_store, TO_PARTY AS receiver_store, sku_dummy AS sku_code, MIN(TRY_TO_DATE(bill_date, \'DD/MM/YYYY\')) AS earliest_bill_date, SUM(ITEM_QUANTITY) AS sto_qty FROM snitch_db.maplemonk.logic_final_sto WHERE origin = \'STORE-STORE\' AND TRY_TO_DATE(bill_date, \'DD/MM/YYYY\') > (SELECT max_date FROM ist_max_date) GROUP BY 1, 2, 3 ), sti_raw AS ( SELECT TRIM(LEFT(FROM_PARTY, LEN(FROM_PARTY) - CHARINDEX(\'-\', REVERSE(FROM_PARTY)))) AS donor_store, TO_PARTY AS receiver_store, sku_dummy AS sku_code, vouch_date AS vouch_date, ITEM_QUANTITY AS sti_qty FROM snitch_db.maplemonk.logic_final_sti WHERE origin = \'STORE-STORE\' ), sti AS ( SELECT r.donor_store, r.receiver_store, r.sku_code, SUM(r.sti_qty) AS sti_qty FROM sti_raw r INNER JOIN sto o ON r.donor_store = o.donor_store AND r.receiver_store = o.receiver_store AND r.sku_code = o.sku_code WHERE r.vouch_date >= o.earliest_bill_date GROUP BY 1, 2, 3 ), donor_receiver_totals AS ( SELECT donor_store, receiver_store, SUM(given_qty) AS total_given_qty FROM ist GROUP BY 1, 2 ), donor_receiver_sto_totals AS ( SELECT donor_store, receiver_store, SUM(sto_qty) AS total_sto_qty FROM sto GROUP BY 1, 2 ), donor_receiver_sti_totals AS ( SELECT donor_store, receiver_store, SUM(sti_qty) AS total_sti_qty FROM sti GROUP BY 1, 2 ), donor_receiver_sto_flag AS ( SELECT d.donor_store, d.receiver_store, CASE WHEN COALESCE(s.total_sto_qty, 0) >= d.total_given_qty * 0.5 THEN TRUE ELSE FALSE END AS is_sto_done FROM donor_receiver_totals d LEFT JOIN donor_receiver_sto_totals s ON d.donor_store = s.donor_store AND d.receiver_store = s.receiver_store ), donor_receiver_sti_flag AS ( SELECT d.donor_store, d.receiver_store, CASE WHEN COALESCE(s.total_sti_qty, 0) >= d.total_given_qty * 0.5 THEN TRUE ELSE FALSE END AS is_sti_done FROM donor_receiver_totals d LEFT JOIN donor_receiver_sti_totals s ON d.donor_store = s.donor_store AND d.receiver_store = s.receiver_store ), combined AS ( SELECT i.donor_store, i.donor_branch_code, i.receiver_store, i.receiver_branch_code, i.sku_code, i.given_qty, COALESCE(o.sto_qty, 0) AS sto_qty, COALESCE(s.sti_qty, 0) AS sti_qty, f.is_sto_done, sf.is_sti_done FROM ist i LEFT JOIN sto o ON i.donor_store = o.donor_store AND i.receiver_store = o.receiver_store AND i.sku_code = o.sku_code LEFT JOIN sti s ON i.donor_store = s.donor_store AND i.receiver_store = s.receiver_store AND i.sku_code = s.sku_code LEFT JOIN donor_receiver_sto_flag f ON i.donor_store = f.donor_store AND i.receiver_store = f.receiver_store LEFT JOIN donor_receiver_sti_flag sf ON i.donor_store = sf.donor_store AND i.receiver_store = sf.receiver_store ), donor_summary AS ( SELECT donor_store AS store, donor_branch_code AS branch_code, SUM(given_qty) AS total_donor_qty, SUM(CASE WHEN NOT is_sto_done THEN given_qty - sto_qty ELSE 0 END) AS donor_pending_qty FROM combined GROUP BY 1, 2 ), receiver_summary AS ( SELECT receiver_store AS store, receiver_branch_code AS branch_code, SUM(given_qty) AS total_receiver_qty, SUM(CASE WHEN NOT is_sti_done THEN given_qty - sti_qty ELSE 0 END) AS receiver_pending_qty FROM combined GROUP BY 1, 2 ), all_stores AS ( SELECT store, branch_code FROM donor_summary UNION SELECT store, branch_code FROM receiver_summary ) SELECT s.store, COALESCE(d.branch_code, r.branch_code) AS branch_code, COALESCE(d.total_donor_qty, 0) AS total_donor_qty, COALESCE(d.total_donor_qty, 0) - COALESCE(d.donor_pending_qty, 0) AS qty_left_donor_inventory, COALESCE(d.donor_pending_qty, 0) AS donor_pending_qty, COALESCE(r.total_receiver_qty, 0) AS total_receiver_qty, COALESCE(r.total_receiver_qty, 0) - COALESCE(r.receiver_pending_qty, 0) AS in_transit_qty, COALESCE(r.total_receiver_qty, 0) - COALESCE(r.receiver_pending_qty, 0) AS received_into_inventory, COALESCE(r.receiver_pending_qty, 0) AS receiver_pending_qty FROM all_stores s LEFT JOIN donor_summary d ON s.store = d.store AND s.branch_code = d.branch_code LEFT JOIN receiver_summary r ON s.store = r.store AND s.branch_code = r.branch_code ORDER BY s.store; create or replace table snitch_db.maplemonk.store_category_delta as WITH south_rule AS ( SELECT \"STORE NAME\" AS store_name, UPPER(TRIM(\"Fresh Order Day\")) AS south_fresh, UPPER(TRIM(\"RPL Order Day\")) AS south_rpl FROM snitch_db.maplemonk.final_southrulebook ), north_rule AS ( SELECT \"STORE NAME\" AS store_name, UPPER(TRIM(\"Fresh Order Day\")) AS north_fresh, UPPER(TRIM(\"RPL Order Day\")) AS north_rpl FROM snitch_db.maplemonk.north_rule_merch ), rulebook AS ( SELECT s.store_name, s.south_fresh, s.south_rpl, n.north_fresh, n.north_rpl FROM south_rule s LEFT JOIN north_rule n ON UPPER(TRIM(s.store_name)) = UPPER(TRIM(n.store_name)) ), branch_details AS ( SELECT a.store AS branch_name, a.store_code::varchar AS branch_code, a.category, a.CLUSTER, b.\"BASE STOCK\" AS base_stock, a.category_mix, a.category_mix*b.\"BASE STOCK\" AS category_base_stock FROM snitch_db.maplemonk.category_mix a LEFT JOIN snitch_db.maplemonk.master_file b ON upper(TRIM(a.store)) = upper(TRIM(b.\"STORE NAME\")) AND upper(TRIM(a.store_code))::varchar = upper(TRIM(b.\"STORE CODE\"))::varchar ), inventory AS ( SELECT branch_code::varchar AS branch_code, new_category AS category, SUM(inventory) AS inventory, SUM(jit_qty) AS jit_qty, SUM(fresh_inventory) AS fresh_inv, SUM(sales_last_7_days) AS sales_7d, ROUND(SUM(sales_last_7_days)/7,0) AS ros_7d, ROUND(SUM(sales_last_30_days)/30,0) AS ros_30d FROM snitch_db.maplemonk.offline_master GROUP BY 1,2 ), lead_time AS ( SELECT g.FINAL_STORE, m.branch_code as branch_code, SUM(g.QTY) AS total_qty, ROUND( SUM(g.QTY * CASE WHEN g.FINAL_STATUS = \'Inward Pending\' THEN 0 WHEN g.EDD <= CURRENT_DATE THEN 1 ELSE DATEDIFF(\'day\', CURRENT_DATE, g.EDD) END) / SUM(g.QTY), 0 ) AS lead_time FROM snitch_db.maplemonk.offline_git_summary g LEFT JOIN ( SELECT DISTINCT branch_code, marketplace_mapped FROM snitch_db.maplemonk.offline_master WHERE branch_code IS NOT NULL ) m ON g.FINAL_STORE = m.marketplace_mapped WHERE g.sku_group NOT LIKE \'4MSFR%\' AND g.sku_group NOT LIKE \'SH0%\' AND g.SKU_GROUP NOT LIKE \'SN%\' AND g.SKU_GROUP NOT LIKE \'4MBL%\' AND g.SKU_GROUP NOT LIKE \'BP%\' AND g.SKU_GROUP NOT LIKE \'%HANGERS%\' AND g.SKU_GROUP NOT LIKE \'%UNIFORM%\' AND g.SKU_GROUP NOT LIKE \'4MCP%\' GROUP BY 1, 2 ), outward AS ( SELECT STORE_CODE, CATEGORY, sum(OUTWARD_QTY) as outward_qty FROM snitch_db.maplemonk.category_level_outward_outward_data group by 1,2 ), fresh_in_jit AS ( SELECT category, TYPE AS order_type, final_store, SUM(qty) AS fresh_qty_jit FROM snitch_db.maplemonk.b2b_journey WHERE FINAL_STATUS NOT IN (\'INWARDED\') AND TYPE like \'%FRESH%\' GROUP BY 1,2,3 ), cut_sizes AS ( select branch_code, new_category as category, count_if( COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 AND new_category IS NOT NULL) as total_skus, COUNT_IF( COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 AND new_category IS NOT NULL AND ( ( LOWER(sku_group) NOT LIKE \'4mbg%\' AND ( (CASE WHEN COALESCE(s_units, 0) + COALESCE(jit_s_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(m_units, 0) + COALESCE(jit_m_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(l_units, 0) + COALESCE(jit_l_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl_units, 0) + COALESCE(jit_xl_units, 0) > 0 THEN 1 ELSE 0 END) ) < 3 or ( (CASE WHEN COALESCE(xs_units, 0) + COALESCE(jit_xs_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(s_units, 0) + COALESCE(jit_s_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(m_units, 0) + COALESCE(jit_m_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(l_units, 0) + COALESCE(jit_l_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl_units, 0) + COALESCE(jit_xl_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xxl_units, 0) + COALESCE(jit_2xl_units, 0) > 0 THEN 1 ELSE 0 END) ) < 4 ) OR ( LOWER(sku_group) LIKE \'4mbg%\' AND ( (CASE WHEN COALESCE(xl3_units, 0) + COALESCE(jit_3xl_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl4_units, 0) + COALESCE(jit_4xl_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl5_units, 0) + COALESCE(jit_5xl_units, 0) > 0 THEN 1 ELSE 0 END) + (CASE WHEN COALESCE(xl6_units, 0) + COALESCE(jit_6xl_units, 0) > 0 THEN 1 ELSE 0 END) ) < 3 ) ) ) AS cut_size_skus, COUNT_IF( COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 AND new_category IS NOT NULL AND ( ( LOWER(sku_group) NOT LIKE \'4mbg%\' AND NOT ( ( COALESCE(s_units, 0) + COALESCE(jit_s_units, 0) > 0 AND COALESCE(m_units, 0) + COALESCE(jit_m_units, 0) > 0 AND COALESCE(l_units, 0) + COALESCE(jit_l_units, 0) > 0 AND COALESCE(xl_units, 0) + COALESCE(jit_xl_units, 0) > 0 ) OR ( COALESCE(s_units, 0) + COALESCE(jit_s_units, 0) > 0 AND COALESCE(m_units, 0) + COALESCE(jit_m_units, 0) > 0 AND COALESCE(l_units, 0) + COALESCE(jit_l_units, 0) > 0 AND COALESCE(xl_units, 0) + COALESCE(jit_xl_units, 0) > 0 ) OR ( COALESCE(m_units, 0) + COALESCE(jit_m_units, 0) > 0 AND COALESCE(l_units, 0) + COALESCE(jit_l_units, 0) > 0 AND COALESCE(xl_units, 0) + COALESCE(jit_xl_units, 0) > 0 AND COALESCE(xxl_units, 0) + COALESCE(jit_2xl_units, 0) > 0 ) ) ) OR ( LOWER(sku_group) LIKE \'4mbg%\' AND NOT ( ( COALESCE(xl3_units, 0) + COALESCE(jit_3xl_units, 0) > 0 AND COALESCE(xl4_units, 0) + COALESCE(jit_4xl_units, 0) > 0 AND COALESCE(xl5_units, 0) + COALESCE(jit_5xl_units, 0) > 0 ) OR ( COALESCE(xl4_units, 0) + COALESCE(jit_4xl_units, 0) > 0 AND COALESCE(xl5_units, 0) + COALESCE(jit_5xl_units, 0) > 0 AND COALESCE(xl6_units, 0) + COALESCE(jit_6xl_units, 0) > 0 ) ) ) ) ) AS cut_size_new_with_jit_skus FROM snitch_db.maplemonk.offline_master GROUP BY 1,2 ), depth_ideal AS ( SELECT branch_code::varchar AS branch_code, MAX(dept_ideal) AS dept_ideal FROM snitch_db.maplemonk.offline_master GROUP BY 1 ), offline_plus AS ( SELECT branch_code::varchar AS branch_code, category, plus_base_stock, current_inv AS plus_inv, jit_qty AS plus_jit_qty, (sales_l7d / 7) AS plus_ros FROM snitch_db.maplemonk.offline_plus_store_delta ), ist_summary AS ( SELECT branch_code, SUM(donor_pending_qty) AS ist_donor_qty, SUM(receiver_pending_qty) AS ist_receiver_qty, SUM(receiver_pending_qty) - SUM(donor_pending_qty) AS ist_net_qty FROM snitch_db.maplemonk.ist_summary_v1 GROUP BY 1 ), main_data AS ( SELECT a.*, IFNULL(b.inventory,0) AS inventory, IFNULL(b.jit_qty,0) AS jit_qty, IFNULL(b.sales_7d,0) AS sales_7d, IFNULL(b.ros_7d,0) AS ros_7d, IFNULL(b.ros_30d,0) as ros_30d, IFNULL(b.fresh_inv,0) AS fresh_inv, IFNULL(c.lead_time,3) AS lead_time, IFNULL(d.outward_qty,0) AS outward_qty, IFNULL(e.fresh_qty_jit,0) AS fresh_qty_jit, IFNULL(f.cut_size_skus,0) AS cut_size_skus, IFNULL(f.cut_size_new_with_jit_skus,0) AS cut_size_skus_new, IFNULL(g.dept_ideal,0) AS dept_ideal, IFNULL(f.total_skus,0) AS total_skus, IFNULL(h.plus_base_stock, 0) AS plus_base_stock, IFNULL(h.plus_inv, 0) AS plus_inv, IFNULL(h.plus_jit_qty, 0) AS plus_jit_qty, IFNULL(h.plus_ros, 0) AS plus_ros, IFNULL(ist.ist_donor_qty, 0) AS ist_donor_qty, IFNULL(ist.ist_receiver_qty, 0) AS ist_receiver_qty, IFNULL(ist.ist_net_qty, 0) AS ist_net_qty, rb.south_fresh, rb.south_rpl, rb.north_fresh, rb.north_rpl FROM branch_details a LEFT JOIN inventory b ON a.branch_code = b.branch_code AND a.category = b.category LEFT JOIN lead_time c ON a.branch_code = c.branch_code LEFT JOIN outward d ON a.branch_code = d.store_code AND a.category = d.category LEFT JOIN fresh_in_jit e ON a.branch_name = e.final_store AND a.category = e.category LEFT JOIN cut_sizes f ON a.branch_code = f.branch_code and a.category=f.category LEFT JOIN depth_ideal g ON a.branch_code = g.branch_code LEFT JOIN offline_plus h ON a.branch_code = h.branch_code AND upper(a.category) = upper(h.category) LEFT JOIN rulebook rb ON UPPER(TRIM(a.branch_name)) = UPPER(TRIM(rb.store_name)) LEFT JOIN ist_summary ist ON a.branch_code = ist.branch_code ) SELECT *, IFNULL((inventory+jit_qty-(ros_7d*lead_time)-outward_qty),0) AS total_inventory, IFNULL( ROUND( GREATEST( category_base_stock - (inventory+jit_qty-(ros_7d*lead_time)-outward_qty), 0 ), 0), 0) AS delta, CASE WHEN UPPER(CLUSTER) IN (\'PUNJAB\', \'UTTAR PRADESH\', \'DELHI\',\'MP\', \'UTTARAKHAND\', \'HARYANA\') THEN \'Anish\' WHEN UPPER(CLUSTER) IN (\'BANGALORE\', \'MANGALORE\', \'KERALA\', \'KARNATAKA\', \'TAMIL NADU\') THEN \'Srushti\' WHEN UPPER(CLUSTER) IN (\'ASSAM\', \'HYDERABAD\', \'RAJASTHAN\', \'CHHATTISGARH\', \'AP\', \'BIHAR\',\'ODISHA\') THEN \'Yuvraj\' WHEN UPPER(CLUSTER) IN (\'GUJARAT\', \'MAHARASHTRA\') THEN \'Priyanka\' ELSE \'Unknown\' END AS CLUSTER_POC, CASE WHEN UPPER(CLUSTER) IN (\'PUNJAB\', \'UTTAR PRADESH\', \'DELHI\',\'MP\',\'UTTARAKHAND\', \'HARYANA\', \'RAJASTHAN\',\'GUJARAT\', \'BIHAR\', \'ASSAM\') THEN \'North\' WHEN UPPER(CLUSTER) IN ( \'BANGALORE\', \'MANGALORE\', \'KERALA\', \'KARNATAKA\',\'TAMIL NADU\', \'HYDERABAD\', \'AP\', \'MAHARASHTRA\',\'ODISHA\',\'CHHATTISGARH\') THEN \'South\' ELSE \'OTHERS\' END AS ZONE, ROUND((base_stock * category_mix) / NULLIF(dept_ideal, 0), 0) AS ideal_option_count FROM main_data; create or replace table snitch_db.maplemonk.offline_plus_store_delta as WITH special_stores AS ( SELECT column1 AS marketplace_mapped FROM VALUES (\'SNITCH - FOCO - VAISHALI NAGAR\'), (\'SNITCH - FOCO - TRION\'), (\'SNITCH - FOCO - SINDHUBHAVAN\'), (\'SNITCH - FOCO - SHYAMAL\'), (\'SNITCH - FOCO - PRAYAGRAJ\'), (\'SNITCH - FOCO - POLARIS VIP ROAD\'), (\'SNITCH - FOCO - DB MALL\'), (\'SNITCH - COFO - VIZAG\'), (\'SNITCH - COFO - VIVIANA THANE\'), (\'SNITCH - COFO - TOLICHOWKI\'), (\'SNITCH - COFO - SKY CITY OBEROI\'), (\'SNITCH - COFO - SARATH CITY\'), (\'SNITCH - COFO - RAJAHMUNDRY\'), (\'SNITCH - COFO - PONDY BAZAAR\'), (\'SNITCH - COFO - MYSURU\'), (\'SNITCH - COFO - LODHA XPERIA\'), (\'SNITCH - COFO - KUKATPALLY\'), (\'SNITCH - COFO - KOTHAPET\'), (\'SNITCH - COFO - KANKARBAGH\'), (\'SNITCH - COFO - KALYAN NAGAR\'), (\'SNITCH - COFO - HIMAYAT NAGAR\'), (\'SNITCH - COFO - GATEWAY MALL\'), (\'SNITCH - COFO - EXPRESS AVENUE\'), (\'SNITCH - COFO - DAHISAR\'), (\'SNITCH - COFO - BRIGADE ROAD\'), (\'SNITCH - COFO - BILASPUR\'), (\'SNITCH - COFO - BANER\'), (\'SNITCH - COCO - VIJAYWADA\'), (\'SNITCH - COCO - SECTOR-50\'), (\'SNITCH - COCO - SECTOR-29\'), (\'SNITCH - COCO - MOTI NAGAR\'), (\'SNITCH - COCO - JANAKPURI\'), (\'SNITCH - COCO - INDIRANAGAR\'), (\'SNITCH - COCO - HSR LAYOUT\'), (\'SNITCH - COCO - HLP MOHALI MALL\'), (\'SNITCH - COCO - GUWAHATI\'), (\'SNITCH - COCO - FARIDABAD\'), (\'SNITCH - COCO - CG ROAD\'), (\'SNITCH - COCO - BEL ROAD\'), (\'SNITCH - COCO - BANASHANKARI\') ), filtered_master AS ( SELECT branch_code, marketplace_mapped, cluster, new_category, inventory, jit_qty, fresh_inventory, sales_last_30_days, sales_last_15_days, sales_last_7_days, xl3_units, xl4_units, xl5_units, xl6_units, jit_3xl_units, jit_4xl_units, jit_5xl_units, jit_6xl_units FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE marketplace_mapped NOT ILIKE \'%WH%\' AND new_category IS NOT NULL AND TRIM(new_category) <> \'\' AND sku_group ILIKE ANY ( \'%4MBG%\', \'%4BRN%\', \'%4BPL%\', \'%4BTR%\', \'%4BCH%\', \'%4BJE%\', \'%4BJK%\', \'%4BSW%\', \'%4BHD%\', \'%4BOS%\', \'%4BSH%\', \'%4BSHS%\', \'%4BSFS%\', \'%4BBL%\', \'%4BCA%\', \'%4BSWT%\', \'%4BCD%\', \'%4BJO%\' ) ), plus_base AS ( SELECT store AS marketplace_mapped, SUM(\"Plus_Size_(Options)\") * 12 AS plus_base_stock, SUM(\"Plus_Size_(Options)\") AS plus_size_options, ROUND( CASE WHEN store IN (SELECT marketplace_mapped FROM special_stores) THEN 0.70 * SUM(\"Plus_Size_(Options)\") ELSE 1.00 * SUM(\"Plus_Size_(Options)\") END, 0 ) AS ideal_topwear_options, ROUND( CASE WHEN store IN (SELECT marketplace_mapped FROM special_stores) THEN 0.30 * SUM(\"Plus_Size_(Options)\") ELSE 0 END, 0 ) AS ideal_bottomwear_options FROM SNITCH_DB.MAPLEMONK.OFFLINE_LONG_TAIL_SHEET1 WHERE LOWER(TRIM(plus_size)) = \'yes\' GROUP BY store ), b2b AS ( SELECT final_store AS branch_name, category, SUM(qty) AS fresh_in_jit FROM SNITCH_DB.MAPLEMONK.B2B_JOURNEY WHERE final_status <> \'INWARDED\' AND LOWER(type) LIKE \'%fresh%\' AND sku ILIKE ANY ( \'%4MBG%\', \'%4BRN%\', \'%4BPL%\', \'%4BTR%\', \'%4BCH%\', \'%4BJE%\', \'%4BJK%\', \'%4BSW%\', \'%4BHD%\', \'%4BOS%\', \'%4BSH%\', \'%4BSHS%\', \'%4BSFS%\', \'%4BBL%\', \'%4BCA%\', \'%4BSWT%\', \'%4BCD%\', \'%4BJO%\' ) GROUP BY final_store, category ), base AS ( SELECT branch_code, marketplace_mapped, cluster, new_category AS category, CASE WHEN new_category IN (\'Cargo Pants\', \'Jeans\', \'Shorts\', \'Trousers\', \'Joggers\') THEN \'Bottom Wear\' ELSE \'Top Wear\' END AS wear_type, SUM(inventory) AS current_inv, SUM(jit_qty) AS jit_qty, SUM(fresh_inventory) AS fresh_inv, SUM(inventory + jit_qty) AS total_inv, SUM(sales_last_30_days) AS sales_l30d, SUM(sales_last_15_days) AS sales_l15d, SUM(sales_last_7_days) AS sales_l7d, COUNT_IF(COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0) AS total_skus, COUNT_IF( COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 AND ( IFF(COALESCE(xl3_units, 0) + COALESCE(jit_3xl_units, 0) > 0, 1, 0) + IFF(COALESCE(xl4_units, 0) + COALESCE(jit_4xl_units, 0) > 0, 1, 0) + IFF(COALESCE(xl5_units, 0) + COALESCE(jit_5xl_units, 0) > 0, 1, 0) + IFF(COALESCE(xl6_units, 0) + COALESCE(jit_6xl_units, 0) > 0, 1, 0) ) < 3 ) AS cut_size_skus, COUNT_IF( COALESCE(inventory, 0) + COALESCE(jit_qty, 0) > 0 AND ( IFF(COALESCE(xl3_units, 0) + COALESCE(jit_3xl_units, 0) > 0, 1, 0) + IFF(COALESCE(xl4_units, 0) + COALESCE(jit_4xl_units, 0) > 0, 1, 0) + IFF(COALESCE(xl5_units, 0) + COALESCE(jit_5xl_units, 0) > 0, 1, 0) + IFF(COALESCE(xl6_units, 0) + COALESCE(jit_6xl_units, 0) > 0, 1, 0) ) >= 3 ) AS current_category_options FROM filtered_master GROUP BY branch_code, marketplace_mapped, cluster, new_category ), final_check AS ( SELECT b.branch_code, b.marketplace_mapped, b.cluster, b.category, b.wear_type, p.plus_base_stock, b.current_inv, b.jit_qty, b.fresh_inv, COALESCE(j.fresh_in_jit, 0) AS fresh_in_jit, GREATEST( b.jit_qty - COALESCE(j.fresh_in_jit, 0), 0 ) AS rpl_in_jit, b.total_inv, b.sales_l30d, b.sales_l15d, b.sales_l7d, b.total_skus, b.cut_size_skus, b.current_category_options, CASE WHEN b.wear_type = \'Top Wear\' THEN p.ideal_topwear_options ELSE p.ideal_bottomwear_options END AS ideal_options, CASE WHEN b.wear_type = \'Top Wear\' THEN p.ideal_topwear_options - b.current_category_options ELSE p.ideal_bottomwear_options - b.current_category_options END AS option_gap, CASE WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Jeans\' THEN \'12%\' WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Shirts\' THEN \'50%\' WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Trousers\' THEN \'15%\' WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'T-Shirts\' THEN \'23%\' WHEN b.marketplace_mapped NOT IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Shirts\' THEN \'80%\' WHEN b.marketplace_mapped NOT IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'T-Shirts\' THEN \'20%\' ELSE \'0%\' END AS mix_percent, CASE WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Jeans\' THEN ROUND(p.plus_size_options * 0.12, 0) WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Shirts\' THEN ROUND(p.plus_size_options * 0.50, 0) WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Trousers\' THEN ROUND(p.plus_size_options * 0.15, 0) WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'T-Shirts\' THEN ROUND(p.plus_size_options * 0.23, 0) WHEN b.marketplace_mapped NOT IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Shirts\' THEN ROUND(p.plus_size_options * 0.80, 0) WHEN b.marketplace_mapped NOT IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'T-Shirts\' THEN ROUND(p.plus_size_options * 0.20, 0) ELSE 0 END AS ideal_category_options, CASE WHEN b.category IN (\'Jeans\', \'Shirts\', \'Trousers\', \'T-Shirts\') THEN b.current_category_options ELSE 0 END AS category_current_options, CASE WHEN b.category IN (\'Jeans\', \'Shirts\', \'Trousers\', \'T-Shirts\') THEN CASE WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Jeans\' THEN ROUND(p.plus_size_options * 0.12, 0) WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Shirts\' THEN ROUND(p.plus_size_options * 0.50, 0) WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Trousers\' THEN ROUND(p.plus_size_options * 0.15, 0) WHEN b.marketplace_mapped IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'T-Shirts\' THEN ROUND(p.plus_size_options * 0.23, 0) WHEN b.marketplace_mapped NOT IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'Shirts\' THEN ROUND(p.plus_size_options * 0.80, 0) WHEN b.marketplace_mapped NOT IN (SELECT marketplace_mapped FROM special_stores) AND b.category = \'T-Shirts\' THEN ROUND(p.plus_size_options * 0.20, 0) ELSE 0 END - b.current_category_options ELSE 0 END AS category_option_gap FROM base b INNER JOIN plus_base p ON b.marketplace_mapped = p.marketplace_mapped LEFT JOIN b2b j ON b.marketplace_mapped = j.branch_name AND b.category = j.category ) SELECT branch_code, marketplace_mapped, cluster, category, wear_type, plus_base_stock, current_inv, jit_qty, fresh_inv, fresh_in_jit, rpl_in_jit, total_inv, sales_l30d, sales_l15d, sales_l7d, total_skus, cut_size_skus, mix_percent AS \"MIX%\", ideal_options AS \"IDEAL OPTIONS\", current_category_options AS \"CURRENT OPTIONS\", ideal_category_options AS \"CATEGORY IDEAL OPTION\", category_current_options AS \"CATEGORY CURRENT OPTIONS\", DENSE_RANK() OVER ( PARTITION BY marketplace_mapped ORDER BY category DESC ) AS rank FROM final_check; CREATE OR REPLACE TABLE snitch_db.maplemonk.outward_options_offline AS WITH BASE AS ( SELECT BRANCH_CODE, MARKETPLACE_MAPPED, UPPER(SKU_GROUP) AS SKU_GROUP, INVENTORY, JIT_QTY, (XS_UNITS + JIT_XS_UNITS) AS TTL_XS, (S_UNITS + JIT_S_UNITS) AS TTL_S, (M_UNITS + JIT_M_UNITS) AS TTL_M, (L_UNITS + JIT_L_UNITS) AS TTL_L, (XL_UNITS + JIT_XL_UNITS) AS TTL_XL, (XXL_UNITS + JIT_2XL_UNITS) AS TTL_XXL, (XL3_UNITS + JIT_3XL_UNITS) AS TTL_3XL, (XL4_UNITS + JIT_4XL_UNITS) AS TTL_4XL, (XL5_UNITS + JIT_5XL_UNITS) AS TTL_5XL, (XL6_UNITS + JIT_6XL_UNITS) AS TTL_6XL, NEW_CATEGORY, STYLE, NUM_SIZE_AVAILABLE, FRESH_INVENTORY FROM SNITCH_DB.MAPLEMONK.OFFLINE_MASTER WHERE UPPER(NEW_CATEGORY) NOT IN (\'BAGS\',\'BELTS\',\'PERFUMES\',\'SHOES\',\'SUNGLASSES\') AND NEW_CATEGORY IS NOT NULL AND BRANCH_CODE IS NOT NULL AND UPPER(MARKETPLACE_MAPPED) NOT IN ( \'SNITCH - WH - B2B\',\'SNITCH - WH - SR\',\'SNITCH - MARKET PLACE - SLIKK\', \'SNITCH - SNITCH X\',\'SNITCH - WH - RAJASTHAN\',\'SNITCH - WH - U.P\', \'SNITCH - WH - M P\',\'SNITCH - WH - GUJARAT\' ) ), CUT_SIZE_FLAGS AS ( SELECT BRANCH_CODE, NEW_CATEGORY, SKU_GROUP, CASE WHEN UPPER(SKU_GROUP) LIKE \'4MBG%\' AND ( (CASE WHEN TTL_XS > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_S > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_M > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_L > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_XXL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_3XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_4XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_5XL > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_6XL > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' WHEN UPPER(SKU_GROUP) NOT LIKE \'4MBG%\' AND ( (CASE WHEN TTL_S > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_M > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_L > 0 THEN 1 ELSE 0 END) + (CASE WHEN TTL_XL > 0 THEN 1 ELSE 0 END) ) < 4 THEN \'YES\' ELSE \'NO\' END AS CUT_SIZE FROM BASE ), FULL_ONLY AS ( SELECT DISTINCT BRANCH_CODE, NEW_CATEGORY, SKU_GROUP FROM CUT_SIZE_FLAGS WHERE CUT_SIZE = \'NO\' ), FRESH_OPTS AS ( SELECT DISTINCT b.BRANCH_CODE, b.NEW_CATEGORY, b.SKU_GROUP FROM BASE b JOIN CUT_SIZE_FLAGS c ON c.BRANCH_CODE = b.BRANCH_CODE AND c.NEW_CATEGORY = b.NEW_CATEGORY AND c.SKU_GROUP = b.SKU_GROUP WHERE c.CUT_SIZE = \'YES\' AND b.INVENTORY > 0 AND b.INVENTORY = b.FRESH_INVENTORY ), AGG AS ( SELECT x.BRANCH_CODE, x.NEW_CATEGORY, COUNT(DISTINCT fo.SKU_GROUP) AS full_only_options, COUNT(DISTINCT fr.SKU_GROUP) AS fresh_options_in_cutsize FROM ( SELECT DISTINCT BRANCH_CODE, NEW_CATEGORY FROM FULL_ONLY UNION SELECT DISTINCT BRANCH_CODE, NEW_CATEGORY FROM FRESH_OPTS ) x LEFT JOIN FULL_ONLY fo ON fo.BRANCH_CODE = x.BRANCH_CODE AND fo.NEW_CATEGORY = x.NEW_CATEGORY LEFT JOIN FRESH_OPTS fr ON fr.BRANCH_CODE = x.BRANCH_CODE AND fr.NEW_CATEGORY = x.NEW_CATEGORY GROUP BY x.BRANCH_CODE, x.NEW_CATEGORY ) SELECT b.branch_name, b.branch_code, b.category, b.base_stock, b.category_mix, b.ideal_option_count, ROUND(b.ideal_option_count * 1.00) AS to_be_maintained_option_count, b.total_skus, COALESCE(a.full_only_options, 0) AS full_only_options, COALESCE(a.fresh_options_in_cutsize, 0) AS fresh_options_in_cutsize, GREATEST( b.total_skus - COALESCE(a.full_only_options, 0) - COALESCE(a.fresh_options_in_cutsize, 0), 0 ) AS outward_options, b.total_skus - GREATEST( b.total_skus - COALESCE(a.full_only_options, 0) - COALESCE(a.fresh_options_in_cutsize, 0), 0 ) AS final_SKUs FROM SNITCH_DB.MAPLEMONK.STORE_CATEGORY_DELTA AS b LEFT JOIN AGG a ON a.BRANCH_CODE = b.BRANCH_CODE AND a.NEW_CATEGORY = b.CATEGORY ORDER BY b.branch_code, b.category; create or replace table snitch_db.maplemonk.offline_non_replen_cut as WITH wh_inv AS ( SELECT warehouse_location AS zone, UPPER(sku_group) AS sku_group, COALESCE(xs_units, 0) AS wh_xs, COALESCE(s_units, 0) AS wh_s, COALESCE(m_units, 0) AS wh_m, COALESCE(l_units, 0) AS wh_l, COALESCE(xl_units, 0) AS wh_xl, COALESCE(xxl_units, 0) AS wh_xxl, COALESCE(xl3_units, 0) AS wh_3xl, COALESCE(xl4_units, 0) AS wh_4xl, COALESCE(xl5_units, 0) AS wh_5xl, COALESCE(xl6_units, 0) AS wh_6xl FROM snitch_db.maplemonk.availability_master_v2_merged ), store_zone AS ( SELECT DISTINCT branch_code, zone FROM snitch_db.maplemonk.store_category_delta ), store_cut_size AS ( SELECT om.branch_code, sz.zone, om.marketplace_mapped, UPPER(om.sku_group) AS sku_group, om.inventory, om.jit_qty, om.new_category, om.designs, om.collar_new, om.sleeve_type, om.fit, om.style, om.material_new, CASE WHEN COALESCE(om.XS_UNITS,0) + COALESCE(om.JIT_XS_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_xs, CASE WHEN COALESCE(om.S_UNITS,0) + COALESCE(om.JIT_S_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_s, CASE WHEN COALESCE(om.M_UNITS,0) + COALESCE(om.JIT_M_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_m, CASE WHEN COALESCE(om.L_UNITS,0) + COALESCE(om.JIT_L_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_l, CASE WHEN COALESCE(om.XL_UNITS,0) + COALESCE(om.JIT_XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_xl, CASE WHEN COALESCE(om.XXL_UNITS,0) + COALESCE(om.JIT_2XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_xxl, CASE WHEN COALESCE(om.XL3_UNITS,0) + COALESCE(om.JIT_3XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_3xl, CASE WHEN COALESCE(om.XL4_UNITS,0) + COALESCE(om.JIT_4XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_4xl, CASE WHEN COALESCE(om.XL5_UNITS,0) + COALESCE(om.JIT_5XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_5xl, CASE WHEN COALESCE(om.XL6_UNITS,0) + COALESCE(om.JIT_6XL_UNITS,0) > 0 THEN 1 ELSE 0 END AS s_6xl, COALESCE(om.XS_UNITS,0) + COALESCE(om.JIT_XS_UNITS,0) AS qty_xs, COALESCE(om.S_UNITS,0) + COALESCE(om.JIT_S_UNITS,0) AS qty_s, COALESCE(om.M_UNITS,0) + COALESCE(om.JIT_M_UNITS,0) AS qty_m, COALESCE(om.L_UNITS,0) + COALESCE(om.JIT_L_UNITS,0) AS qty_l, COALESCE(om.XL_UNITS,0) + COALESCE(om.JIT_XL_UNITS,0) AS qty_xl, COALESCE(om.XXL_UNITS,0) + COALESCE(om.JIT_2XL_UNITS,0) AS qty_xxl, COALESCE(om.XL3_UNITS,0) + COALESCE(om.JIT_3XL_UNITS,0) AS qty_3xl, COALESCE(om.XL4_UNITS,0) + COALESCE(om.JIT_4XL_UNITS,0) AS qty_4xl, COALESCE(om.XL5_UNITS,0) + COALESCE(om.JIT_5XL_UNITS,0) AS qty_5xl, COALESCE(om.XL6_UNITS,0) + COALESCE(om.JIT_6XL_UNITS,0) AS qty_6xl FROM snitch_db.maplemonk.offline_master om LEFT JOIN store_zone sz ON om.branch_code = sz.branch_code WHERE om.new_category NOT IN (\'Belts\', \'Bags\', \'Shoes\', \'Sunglasses\', \'Perfumes\') AND om.inventory + om.jit_qty > 0 AND om.base_stock IS NOT NULL ), cut_size_flagged AS ( SELECT s.*, CASE WHEN LEFT(s.SKU_GROUP, 4) IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND (s.s_3xl + s.s_4xl + s.s_5xl + s.s_6xl) < 3 THEN \'YES\' WHEN LEFT(s.SKU_GROUP, 4) NOT IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND ( (s.s_s + s.s_m + s.s_l + s.s_xl) < 3 OR (s.s_xs + s.s_s + s.s_m + s.s_l + s.s_xl + s.s_xxl) < 4 ) THEN \'YES\' ELSE \'NO\' END AS cut_size_at_store FROM store_cut_size s ), cut_size_only AS ( SELECT * FROM cut_size_flagged where cut_size_at_store in (\'YES\') ), with_replenishment AS ( SELECT c.*, CASE WHEN c.qty_xs + COALESCE(w.wh_xs,0) > 2 THEN 1 ELSE 0 END AS r_xs, CASE WHEN c.qty_s + COALESCE(w.wh_s,0) > 3 THEN 1 ELSE 0 END AS r_s, CASE WHEN c.qty_m + COALESCE(w.wh_m,0) > 5 THEN 1 ELSE 0 END AS r_m, CASE WHEN c.qty_l + COALESCE(w.wh_l,0) > 5 THEN 1 ELSE 0 END AS r_l, CASE WHEN c.qty_xl + COALESCE(w.wh_xl,0) > 3 THEN 1 ELSE 0 END AS r_xl, CASE WHEN c.qty_xxl + COALESCE(w.wh_xxl,0) > 2 THEN 1 ELSE 0 END AS r_xxl, CASE WHEN c.qty_3xl + COALESCE(w.wh_3xl,0) > 3 THEN 1 ELSE 0 END AS r_3xl, CASE WHEN c.qty_4xl + COALESCE(w.wh_4xl,0) > 3 THEN 1 ELSE 0 END AS r_4xl, CASE WHEN c.qty_5xl + COALESCE(w.wh_5xl,0) > 3 THEN 1 ELSE 0 END AS r_5xl, CASE WHEN c.qty_6xl + COALESCE(w.wh_6xl,0) > 3 THEN 1 ELSE 0 END AS r_6xl FROM cut_size_only c LEFT JOIN wh_inv w ON w.zone = c.zone AND w.sku_group = c.sku_group ), final AS ( SELECT r.*, CASE WHEN LEFT(r.SKU_GROUP, 4) IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND (r.r_3xl + r.r_4xl + r.r_5xl + r.r_6xl) < 3 THEN \'YES\' WHEN LEFT(r.SKU_GROUP, 4) NOT IN ( \'4MBG\', \'4BRN\', \'4BPL\', \'4BTR\', \'4BCH\', \'4BJE\', \'4BJK\', \'4BSW\', \'4BHD\', \'4BOS\', \'4BSH\', \'4BSF\', \'4BBL\', \'4BCA\', \'4BCD\', \'4BJO\' ) AND ( (r.r_s + r.r_m + r.r_l + r.r_xl) < 3 OR (r.r_xs + r.r_s + r.r_m + r.r_l + r.r_xl + r.r_xxl) < 4 ) THEN \'YES\' ELSE \'NO\' END AS cut_size_after_replenishment FROM with_replenishment r ) SELECT branch_code, zone, marketplace_mapped, sku_group, inventory, jit_qty, new_category, designs, collar_new, sleeve_type, fit, style, material_new, cut_size_at_store, cut_size_after_replenishment FROM final WHERE cut_size_after_replenishment = \'YES\' ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            